import{_ as l,a0 as s,w as d,s as r,I as o,x as t,a1 as p,A as n,ao as a}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const I=JSON.parse('{"title":"如何在 FreeDOS 上归档文件 | LCTT x X-CMD","titleTemplate":false,"description":"如何在 FreeDOS 上归档文件 | LCTT (202107) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何在 FreeDOS 上归档文件 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何在 FreeDOS 上归档文件 | LCTT (202107) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202107/20210628 How to archive files on FreeDOS","title":"如何在 FreeDOS 上归档文件","tag":"202107","desc":""},"relativePath":"202107/20210628 How to archive files on FreeDOS.md","filePath":"[post].md"}'),u={name:"202107/20210628 How to archive files on FreeDOS.md"};function m(f,e,Z,P,S,D){const i=s("Link");return d(),r("div",null,[e[22]||(e[22]=o("h1",{id:"如何在-freedos-上归档文件",tabindex:"-1"},[t("如何在 FreeDOS 上归档文件 "),o("a",{class:"header-anchor",href:"#如何在-freedos-上归档文件","aria-label":"Permalink to “如何在 FreeDOS 上归档文件”"},"​")],-1)),e[23]||(e[23]=o("blockquote",null,[o("p",null,"虽然有一个 FreeDOS 版的 tar，但 DOS 上事实上的标准归档工具是 Zip 和 Unzip。")],-1)),e[24]||(e[24]=o("p",null,[o("img",{src:"https://img.linux.net.cn/data/attachment/album/202107/10/063340wp088ozz1fo9f1e1.jpg",alt:""})],-1)),e[25]||(e[25]=o("p",null,[t("在 Linux 上，你可能熟悉标准的 Unix 归档命令："),o("code",null,"tar"),t("。FreeDOS 上也有 "),o("code",null,"tar"),t(" 的版本（还有其他一些流行的归档程序），但 DOS 上事实上的标准归档程序是 Zip 和 Unzip。Zip 和 Unzip 都默认安装在 FreeDOS 1.3 RC4 中。")],-1)),o("p",null,[e[1]||(e[1]=t("Zip 文件格式最初是由 PKWARE 的 Phil Katz 在 1989 年为 PKZIP 和 PKUNZIP 这对 DOS 归档工具构思的。Katz 将 Zip 文件的规范作为一个开放标准发布，因此任何人都可以创建 Zip 档案。作为开放规范的结果，Zip 成为 DOS 上的一个标准归档格式。",-1)),p(i,{href:"http://infozip.sourceforge.net/"},{default:n(()=>[...e[0]||(e[0]=[t("Info-ZIP",-1)])]),_:1}),e[2]||(e[2]=t(" 项目实现了一套开源的 ",-1)),e[3]||(e[3]=o("code",null,"ZIP",-1)),e[4]||(e[4]=t(" 和 ",-1)),e[5]||(e[5]=o("code",null,"UNZIP",-1)),e[6]||(e[6]=t(" 程序。",-1))]),e[26]||(e[26]=a('<h3 id="对文件和目录进行压缩" tabindex="-1">对文件和目录进行压缩 <a class="header-anchor" href="#对文件和目录进行压缩" aria-label="Permalink to “对文件和目录进行压缩”">​</a></h3><p>你可以在 DOS 命令行中使用 <code>ZIP</code> 来创建文件和目录的归档。这是一个方便的方法，可以为你的工作做一个备份，或者发布一个“包”，在未来的 FreeDOS 发布中使用。例如，假设我想为我的项目源码做一个备份，其中包含这些源文件：</p><p><img src="https://opensource.com/sites/default/files/uploads/dir.png" alt="dir" title="I&#39;d like to archive these files"></p><p><em>我想把这些文件归档</em></p><p><code>ZIP</code> 有大量的命令行选项来做不同的事情，但我最常使用的命令行选项是 <code>-r</code> 来处理目录和子目录 <em>递归</em>，以及使用 <code>-9</code> 来提供可能的最大压缩。<code>ZIP</code> 和 <code>UNZIP</code> 使用类似 Unix 的命令行，所以你可以在破折号后面组合选项：<code>-9r</code> 将提供最大压缩并在 Zip 文件中包括子目录。</p><p><img src="https://opensource.com/sites/default/files/uploads/zip-9r.png" alt="zip" title="Zipping a directory tree"></p><p><em>压缩一个目录树</em></p><p>在我的例子中，<code>ZIP</code> 能够将我的源文件从大约 33KB 压缩到大约 22KB，为我节省了 11KB 的宝贵磁盘空间。你可能会得到不同的压缩率，这取决于你给 <code>ZIP</code> 的选项，或者你想在 Zip 文件中存储什么文件（以及有多少）。一般来说，非常长的文本文件（如源码）会产生良好的压缩效果，而非常小的文本文件（如只有几行的 DOS “批处理”文件）通常太短，无法很好地压缩。</p><h3 id="解压文件和目录" tabindex="-1">解压文件和目录 <a class="header-anchor" href="#解压文件和目录" aria-label="Permalink to “解压文件和目录”">​</a></h3><p>将文件保存到 Zip 文件中是很好的，但你最终会需要将这些文件解压到某个地方。让我们首先检查一下我们刚刚创建的 Zip 文件里有什么。为此，使用 <code>UNZIP </code>命令。你可以在 <code>UNZIP</code>中使用一堆不同的选项，但我发现我只使用几个常用的选项。</p><p>要列出一个 Zip 文件的内容，使用 <code>-l</code> （“list”） 选项。</p><p><img src="https://opensource.com/sites/default/files/uploads/unzip-l.png" alt="unzip -l" title="Listing the archive file contents with unzip"></p><p><em>用 unzip 列出归档文件的内容</em></p><p>该输出允让我看到 Zip 文件中的 14 个条目：13 个文件加上 <code>SRC</code> 目录。</p><p>如果我想提取整个 Zip 文件，我可以直接使用 <code>UNZIP</code> 命令并提供 Zip 文件作为命令行选项。这样就可以从我当前的工作目录开始提取 Zip 文件了。除非我正在恢复某个东西的先前版本，否则我通常不想覆盖我当前的文件。在这种情况下，我希望将 Zip 文件解压到一个新的目录。你可以用 <code>-d</code> （“destination”） 命令行选项指定目标路径。</p><p><img src="https://opensource.com/sites/default/files/uploads/unzip-d.png" alt="unzip -d temp" title="You can unzip into a destination path with -d"></p><p><em>你可以用 -d 来解压到目标路径</em></p><p>有时我想从一个 Zip 文件中提取一个文件。在这个例子中，假设我想提取一个 DOS 可执行程序 <code>TEST.EXE</code>。要提取单个文件，你要指定你想提取的 Zip 文件的完整路径。默认情况下，<code>UNZIP</code> 将使用 Zip 文件中提供的路径解压该文件。要省略路径信息，你可以添加 <code>-j</code>（“junk the path”） 选项。</p><p>你也可以组合选项。让我们从 Zip 文件中提取 <code>SRC\\TEST.EXE</code> 程序，但省略完整路径并将其保存在 <code>TEMP</code> 目录下：</p><p><img src="https://opensource.com/sites/default/files/uploads/unzip-j.png" alt="unzip -j" title="Combining options with unzip"></p><p><em>unzip 组合选项</em></p><p>因为 Zip 文件是一个开放的标准，所以我们会今天继续看到 Zip 文件。每个 Linux 发行版都可以通过 Info-ZIP 程序支持 Zip 文件。你的 Linux 文件管理器可能也支持 Zip 文件。在 GNOME 文件管理器中，你应该可以右击一个文件夹并从下拉菜单中选择“压缩”。你可以选择创建一个包括 Zip 文件在内的新的归档文件。</p><p>创建和管理 Zip 文件是任何 DOS 用户的一项关键技能。你可以在 Info-ZIP 网站上了解更多关于 <code>ZIP</code> 和 <code>UNZIP</code> 的信息，或者在命令行上使用 <code>h</code>（“帮助”）选项来打印选项列表。</p><hr>',24)),o("p",null,[e[8]||(e[8]=t("via: ",-1)),p(i,{href:"https://opensource.com/article/21/6/archive-files-freedos"},{default:n(()=>[...e[7]||(e[7]=[t("https://opensource.com/article/21/6/archive-files-freedos",-1)])]),_:1})]),o("p",null,[e[13]||(e[13]=t("作者：",-1)),p(i,{href:"https://opensource.com/users/jim-hall"},{default:n(()=>[...e[9]||(e[9]=[t("Jim Hall",-1)])]),_:1}),e[14]||(e[14]=t(" 选题：",-1)),p(i,{href:"https://github.com/lujun9972"},{default:n(()=>[...e[10]||(e[10]=[t("lujun9972",-1)])]),_:1}),e[15]||(e[15]=t(" 译者：",-1)),p(i,{href:"https://github.com/geekpi"},{default:n(()=>[...e[11]||(e[11]=[t("geekpi",-1)])]),_:1}),e[16]||(e[16]=t(" 校对：",-1)),p(i,{href:"https://github.com/wxy"},{default:n(()=>[...e[12]||(e[12]=[t("wxy",-1)])]),_:1})]),o("p",null,[e[19]||(e[19]=t("本文由 ",-1)),p(i,{href:"https://github.com/LCTT/TranslateProject"},{default:n(()=>[...e[17]||(e[17]=[t("LCTT",-1)])]),_:1}),e[20]||(e[20]=t(" 原创编译，",-1)),p(i,{href:"https://linux.cn/"},{default:n(()=>[...e[18]||(e[18]=[t("Linux中国",-1)])]),_:1}),e[21]||(e[21]=t(" 荣誉推出",-1))])])}const O=l(u,[["render",m]]);export{I as __pageData,O as default};
